// A damped spring field with positional circle collisions. No DOM dependency.
export class BubbleField {
  constructor(){this.bodies=[];this.width=400;this.height=400;this.dragId=null;}
  resize(w,h){this.width=w;this.height=h;}
  reconcile(specs){const existing=new Map(this.bodies.map(b=>[b.id,b]));const wanted=new Set();for(const s of specs){wanted.add(s.id);let b=existing.get(s.id);if(!b){b={...s,x:s.spawnX??s.tx,y:s.spawnY??s.ty,vx:0,vy:0,r:1,alpha:0};this.bodies.push(b)}Object.assign(b,s,{targetAlpha:1,retired:false});}for(const b of this.bodies)if(!wanted.has(b.id)){b.retired=true;b.targetAlpha=0;b.targetR=0;}}
  step(dt){dt=Math.min(Math.max(dt,0),1/30);const ease=1-Math.exp(-9*dt),damping=Math.exp(-6.5*dt);for(const b of this.bodies){b.r+=(b.targetR-b.r)*ease;b.alpha+=((b.targetAlpha??1)-b.alpha)*ease;if(b.id===this.dragId)continue;b.vx+=(b.tx-b.x)*19*dt;b.vy+=(b.ty-b.y)*19*dt;b.vx*=damping;b.vy*=damping;const speed=Math.hypot(b.vx,b.vy);if(speed>1400){b.vx*=1400/speed;b.vy*=1400/speed}b.x+=b.vx*dt;b.y+=b.vy*dt;const pad=b.r+7;if(b.x<pad)b.x+=(pad-b.x)*ease;if(b.x>this.width-pad)b.x+=(this.width-pad-b.x)*ease;if(b.y<pad)b.y+=(pad-b.y)*ease;if(b.y>this.height-pad)b.y+=(this.height-pad-b.y)*ease;}
    for(let iteration=0;iteration<3;iteration++){const cell=Math.max(12,...this.bodies.map(b=>b.r*2+3)),grid=new Map();for(const b of this.bodies){if(b.retired||b.alpha<.1)continue;const gx=Math.floor(b.x/cell),gy=Math.floor(b.y/cell);for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++){for(const other of grid.get(`${gx+dx},${gy+dy}`)||[]){const ax=b.x-other.x,ay=b.y-other.y;let distance=Math.hypot(ax,ay);const overlap=b.r+other.r+2-distance;if(overlap<=0)continue;const seed=(String(b.id)+String(other.id)).split('').reduce((n,c)=>n+c.charCodeAt(0),0)*2.3999632297;const nx=distance>.001?ax/distance:Math.cos(seed),ny=distance>.001?ay/distance:Math.sin(seed);const invA=b.id===this.dragId?0:1/Math.max(1,b.r*b.r),invB=other.id===this.dragId?0:1/Math.max(1,other.r*other.r);if(invA+invB===0)continue;const correction=overlap*.88/(invA+invB);b.x+=nx*correction*invA;b.y+=ny*correction*invA;other.x-=nx*correction*invB;other.y-=ny*correction*invB;}}const key=`${gx},${gy}`;if(!grid.has(key))grid.set(key,[]);grid.get(key).push(b);}}
    this.bodies=this.bodies.filter(b=>!b.retired||b.alpha>.015);
  }
  hit(x,y){return [...this.bodies].reverse().find(b=>!b.retired&&b.alpha>.5&&Math.hypot(x-b.x,y-b.y)<=b.r+4);}
}
